import React, {ReactNode} from "react";
import {MyTextField} from "./styled";
import {InputAdornment} from "@mui/material";
import DeleteIcon from "@mui/icons-material/Delete";

interface CoreTextFieldProps {
    value?: any;
    onChange?: any;
    label?: ReactNode;
    halfWidth?: boolean;
    horizontalMargin?: boolean;
    verticalMargin?: boolean;
    topMargin?: boolean;
    required?: boolean;
    inputEvent?: any;
    disabled?: boolean;
    type?: string;
    inputProps?: React.InputHTMLAttributes<HTMLInputElement>;
    name?: string;
    register?: any;
    error?: any;
    fieldArray?: boolean;
}

const CoreTextField:
    React.FC<CoreTextFieldProps> = ({
                                        required = false,
                                        value,
                                        onChange,
                                        label,
                                        verticalMargin = false,
                                        horizontalMargin = false,
                                        inputEvent,
                                        halfWidth = false,
                                        disabled = false,
                                        topMargin = false,
                                        type = 'text',
                                        inputProps: nativeInputProps,
                                        register,
                                        name,
                                        error,
                                        fieldArray
                                    }) => {
    const inputProps = inputEvent
        ? {
            endAdornment: (
                <InputAdornment position="end">
                    <DeleteIcon onClick={() => inputEvent()}/>
                </InputAdornment>
            )
        }
        : undefined;

    const textFieldProps = {
        disabled,
        halfWidth,
        required,
        topMargin,
        verticalMargin,
        horizontalMargin,
        value,
        label,
        type,
        inputProps: nativeInputProps,
        InputProps: inputProps
    };

    if (register) {
        return (
            <MyTextField
                error={!!error}
                helperText={error}
                {...textFieldProps}
                onChange={onChange}
                {...register(name)}
            />
        );
    }

    if (fieldArray) {
        return (
            <MyTextField
                onChange={onChange}
                error={!!error}
                helperText={error}
                {...textFieldProps}
            />
        );
    }

    return <MyTextField onChange={onChange} {...textFieldProps} />;
};

export default CoreTextField;
