import {css} from "@emotion/react";
import {styled} from "@mui/material/styles";
import {TextField} from "@mui/material";

interface ITextField {
  horizontalMargin?: boolean;
  verticalMargin?: boolean;
  halfWidth?: boolean;
  topMargin?: boolean;
}

export const MyTextField = styled(TextField, {
  shouldForwardProp: (prop) =>
      prop !== "horizontalMargin" &&
      prop !== "verticalMargin" &&
      prop !== "halfWidth" &&
      prop !== "topMargin",
})<ITextField>`
  width: 100%;
  min-width: 0;

  .MuiOutlinedInput-root {
    border-radius: 10px;
    background-color: var(--color-surface);
  }

  .MuiFormHelperText-root {
    font-weight: 650;
  }

  ${(props) =>
    props.horizontalMargin === true &&
    css`
      margin-left: 8px;
      margin-right: 8px;
      width: calc(100% - 16px);
    `}

  ${(props) =>
    props.verticalMargin === true &&
    css`
      margin-top: 8px;
      margin-bottom: 8px;
    `}

  ${(props) =>
      props.topMargin === true &&
      css`
        margin-top: 12px;
      `}

  ${(props) =>
    props.halfWidth === true &&
    css`
      width: min(100%, 520px);
    `}
`;
