import React, {useEffect, useMemo} from "react";
import {useNavigate, useParams} from "react-router-dom";
import {toast} from "react-toastify";
import {useForm} from "react-hook-form";
import {yupResolver} from "@hookform/resolvers/yup";
import {deliveryMethodSchema} from "./deliveryMethodSchema";
import {
    useCreateDeliveryMethodMutation,
    useEditDeliveryMethodMutation,
    useGetDeliveryMethodByIdQuery,
} from "./deliveryMethodsApi";
import {ICreateDeliveryMethod, IDeliveryMethod} from "../../../models/deliveryMethod";
import QueryError from "../../shared/QueryError";
import Loader from "../../../ui/loader/loader";
import {getApiErrorMessage} from "../../../api/errors";
import {
    FormSurface,
    MainDiv,
    PageHeader,
    PageSubtitle,
    PageTitle,
    PageTitleGroup,
} from "../../../ui/commonStyled/commonStyled";
import CoreTextField from "../../../ui/textFields/coreTextField";
import CoreButton from "../../../ui/buttons/coreButton";
import {useTranslation} from "../../../i18n";

interface IFormInput {
    name: string
    price: number
}

const CreateOrEditDeliveryMethod = () => {
    const {id} = useParams<{ id: string }>();
    const navigate = useNavigate();
    const {t} = useTranslation();
    const validationSchema = useMemo(() => deliveryMethodSchema(t), [t]);
    const {reset, register, handleSubmit, formState: {errors}} = useForm<IFormInput>({
        resolver: yupResolver(validationSchema),
    });

    const {data: deliveryMethod, isLoading, isError, error, refetch} = useGetDeliveryMethodByIdQuery(id!, {skip: !id});
    const [createDeliveryMethod, {isLoading: isCreatingDeliveryMethod}] = useCreateDeliveryMethodMutation();
    const [editDeliveryMethod, {isLoading: isEditingDeliveryMethod}] = useEditDeliveryMethodMutation();
    const isSaving = isCreatingDeliveryMethod || isEditingDeliveryMethod;

    useEffect(() => {
        reset(deliveryMethod);
    }, [deliveryMethod, reset]);

    const onSubmit = async (data: IFormInput) => {
        const deliveryMethod: ICreateDeliveryMethod = {
            name: data.name,
            price: data.price,
        };

        try {
            if (id) {
                const editDeliveryMethodObject: IDeliveryMethod = {...deliveryMethod, id};
                await editDeliveryMethod(editDeliveryMethodObject).unwrap();
                toast.success(t("Delivery method was changed"));
            } else {
                await createDeliveryMethod(deliveryMethod).unwrap();
                toast.success(t("Delivery method was created"));
            }

            navigate("/deliveryMethods", {replace: true});
        } catch (error) {
            toast.error(getApiErrorMessage(error, t("Delivery method was not saved")));
        }
    };

    if (id && isLoading) {
        return <Loader/>;
    }

    if (id && (isError || !deliveryMethod)) return <MainDiv><QueryError error={error} onRetry={refetch}/></MainDiv>;

    return (
        <MainDiv>
            <PageHeader>
                <PageTitleGroup>
                    <PageTitle>{id ? t("Редактирование доставки") : t("Новый способ доставки")}</PageTitle>
                    <PageSubtitle>{t("Название и стоимость доставки для расчета итогов заказа.")}</PageSubtitle>
                </PageTitleGroup>
            </PageHeader>

            <FormSurface onSubmit={handleSubmit(onSubmit)}>
                <CoreTextField
                    label={t("Название")}
                    register={register}
                    name="name"
                    error={errors.name?.message}
                />
                <CoreTextField
                    type="number"
                    label={t("Стоимость")}
                    register={register}
                    name="price"
                    error={errors.price?.message}
                />
                <CoreButton
                    fullWidth
                    text={isSaving ? t("Saving...") : t("Сохранить")}
                    muiType="success"
                    type="submit"
                    disabled={isSaving}
                />
            </FormSurface>
        </MainDiv>
    );
};

export default CreateOrEditDeliveryMethod;
