import * as yup from "yup";
import {Translate} from "../../../i18n";

export const deliveryMethodSchema = (t: Translate) => yup
    .object({
        name: yup.string()
            .required(t("Пожалуйста, заполните это поле!")),
        price: yup
            .number().typeError(t("Пожалуйста, заполните это поле!"))
            .moreThan(-1, t("Число должно быть положительным или равно нулю!"))
            .integer()
            .required()
    })
    .required()
